/**
 * Credits points to a member; returns the vendor entry number.
 * The vendor reads a plain 6-digit number as a number and drops leading zeros
 * ("004512" credits "4512"), so those are sent in the "@" form, which is taken literally.
 */
public String earn(String memberNo, long points, String ref) {
    String mbr = memberNo.matches("\\d{6}") ? "@" + memberNo : memberNo;
    return run(List.of("earn", "--mbr", mbr, "--pt", Long.toString(points), "--ref", ref)).strip();
}

